// Récupère du contexte public sur l'entreprise UNIQUEMENT via une source autorisée.
// Par défaut : pas de scraping — on n'utilise que la description de l'offre + le site officiel
// de l'entreprise si l'URL est un domaine propre (jamais un moteur de recherche tiers en
// violation de ses conditions d'utilisation).
// Si votre organisation dispose d'une API de recherche autorisée (ex. Bing Web Search API avec
// clé), configurez COMPANY_SEARCH_API_URL / le credential associé et adaptez ce node en HTTP
// Request vers cette API officielle plutôt que de scraper un moteur de recherche.
const job = $json;
return [{ json: { ...job, public_context_excerpt: '' } }];

const job = $json;
const webContext = job.public_context_excerpt || '';

const systemPrompt = `Tu es COMPANY_RESEARCHER. Identifie: industrie, taille approximative, technologies mentionnées, posture cybersécurité, environnement cloud, présence Microsoft, projets récents, culture/département. Étiquette CHAQUE champ SUPPORTED (source fournie explicite), INFERRED (déduction raisonnable, jamais un fait) ou UNKNOWN (aucune info fiable - ne devine jamais). Réponds UNIQUEMENT via l'outil return_company_research.`;
const userMessage = JSON.stringify({ company_name: job.company, job_title: job.title, job_description: job.description, public_context_excerpt: webContext });

return [{ json: { ...job, research_system_prompt: systemPrompt, research_user_message: userMessage } }];

return $input.all().map(item => {
  const body = item.json;
  const toolUse = (body.content || []).find(c => c.type === 'tool_use');
  const research = toolUse ? toolUse.input : {};
  const job = $('Build_Company_Research_Request').first().json;
  return { json: { ...job, company_research: { ...research, model: body.model } } };
});
